command:
cd /app && python3 - <<'PY'
path = 'parsing/html/reader.go'
s = open(path).read()

old = '''// readRawText consumes content until the matching end tag for name and
// returns it verbatim.
func (t *tokenizer) readRawText(name string) (string, error) {
\tcloseTag := "</" + name
\tlower := strings.ToLower(string(t.data[t.pos:]))
\tidx := strings.Index(lower, closeTag)
\tif idx < 0 {
\t\trest := string(t.data[t.pos:])
\t\tt.pos = len(t.data)
\t\treturn rest, nil
\t}
\tcontent := string(t.data[t.pos : t.pos+idx])
\tt.pos += idx
\t// Consume the end tag.
\tfor !t.eof() && t.data[t.pos] != '>' {
\t\tt.pos++
\t}
\tif !t.eof() {
\t\tt.pos++
\t}
\treturn content, nil
}'''

new = '''// readRawText consumes content until the matching end tag for name and
// returns it verbatim.
func (t *tokenizer) readRawText(name string) (string, error) {
\tcloseTag := "</" + name
\tidx := indexFold(t.data[t.pos:], closeTag)
\tif idx < 0 {
\t\trest := string(t.data[t.pos:])
\t\tt.pos = len(t.data)
\t\treturn rest, nil
\t}
\tcontent := string(t.data[t.pos : t.pos+idx])
\tt.pos += idx
\t// Consume the end tag.
\tfor !t.eof() && t.data[t.pos] != '>' {
\t\tt.pos++
\t}
\tif !t.eof() {
\t\tt.pos++
\t}
\treturn content, nil
}

// indexFold returns the index of the first occurrence of needle in
// haystack, ignoring ASCII case.
func indexFold(haystack []byte, needle string) int {
\tif len(needle) == 0 {
\t\treturn 0
\t}
\tfor i := 0; i+len(needle) <= len(haystack); i++ {
\t\tmatch := true
\t\tfor j := 0; j < len(needle); j++ {
\t\t\tif lowerByte(haystack[i+j]) != lowerByte(needle[j]) {
\t\t\t\tmatch = false
\t\t\t\tbreak
\t\t\t}
\t\t}
\t\tif match {
\t\t\treturn i
\t\t}
\t}
\treturn -1
}

func lowerByte(c byte) byte {
\tif c >= 'A' && c <= 'Z' {
\t\treturn c + 'a' - 'A'
\t}
\treturn c
}'''

assert old in s
s = s.replace(old, new)
open(path, 'w').write(s)
PY
gofmt -w parsing/html/reader.go && go build ./parsing/html/ && go test ./parsing/html/ -v 2>&1 | tail -10
